r=[]
r.append(R(6586871,"मीठा और तीखा डिपिंग सॉस",
"यह डिपिंग सॉस एग रोल, चिकन विंग्स, कुरकुरे टोफ़ू या क्रैब केक के लिए एकदम सही है और इसे बनाना बहुत आसान है!",
"8","1 बड़ा चम्मच",
["1 छोटा चम्मच थाई शैली का चिली गार्लिक सॉस (या कोई अन्य हॉट सॉस)","1/2 कप बिना चीनी मिला खुबानी का प्रिज़र्व (कम चीनी वाला)","1 छोटा चम्मच सोया सॉस (कम सोडियम वाला)"],
["बनाने के लिए, 1/2 कप कम चीनी वाला खुबानी का प्रिज़र्व, 1 बड़ा चम्मच थाई शैली का चिली गार्लिक सॉस (या कोई अन्य हॉट सॉस) और 1 बड़ा चम्मच कम सोडियम वाला सोया सॉस एक कटोरे में मिलाएँ और","माइक्रोवेव में 30 सेकंड गरम करें।"]))
r.append(R(6586894,"पालक और फ़ेटा एग व्हाइट ऑमलेट",
"यह हल्का और स्वादिष्ट ऑमलेट भुनी हुई सब्ज़ियों और खट्टे फ़ेटा से भरा है, और फ़ाइबर से भरपूर, संतुलित भोजन के लिए अंकुरित साबुत अनाज के टोस्ट के साथ परोसा जाता है। ज़्यादातर अंडे की सफ़ेदी का उपयोग संतृप्त वसा को कम रखता है, जबकि फिर भी संतोषजनक प्रोटीन देता है। यह मधुमेह वाले उन लोगों के लिए एक बढ़िया नाश्ता विकल्प है जो स्वाद से समझौता किए बिना रक्त ग्लूकोज़ (ब्लड शुगर) को स्थिर रखना चाहते हैं। यह DASH (डायटरी अप्रोच टू स्टॉप हाइपरटेंशन), शाकाहारी रेसिपी है, और कम वसा और कम कार्ब वाली रेसिपी है।",
"4","1 ऑमलेट और टोस्ट का 1 टुकड़ा",
["4 बड़े अंडे","3/4 कप अंडे की सफ़ेदी","1/4 छोटा चम्मच पिसी काली मिर्च","1/8 छोटा चम्मच लहसुन पाउडर","1/8 छोटा चम्मच स्मोक्ड पैपरिका","1 छोटा चम्मच जैतून का तेल","1/4 कप लाल प्याज़ (बारीक टुकड़ों में कटा हुआ)","1 साबुत लाल शिमला मिर्च (बारीक टुकड़ों में कटी हुई)","1 कप ताज़ा बेबी पालक (कटा हुआ)","1 परत नॉनस्टिक कुकिंग स्प्रे","4 छोटे चम्मच फ़ैट-फ़्री फ़ेटा चीज़ (चूरा किया हुआ)","4 स्लाइस अंकुरित साबुत अनाज की, एज़ेकिएल 4:9 बिना आटे की ब्रेड, कम सोडियम वाली"],
["अंडे और अंडे की सफ़ेदी को एक मध्यम कटोरे में रखें। काली मिर्च, लहसुन पाउडर और स्मोक्ड पैपरिका के साथ फेंटकर मिलाएँ।","एक नॉनस्टिक कड़ाही में मध्यम आँच पर जैतून का तेल गरम करें। लाल प्याज़ और शिमला मिर्च डालें। नरम होने तक 2–3 मिनट भूनें। पालक डालें और गलने तक 1–2 मिनट और पकाएँ। सब्ज़ियों को कड़ाही से निकालें और अलग रख दें।","कड़ाही को पोंछकर साफ़ करें और उस पर कुकिंग स्प्रे करें। वापस मध्यम-धीमी आँच पर रखें। अंडे के मिश्रण का 1/4 भाग कड़ाही में डालें और बराबर फैलाने के लिए उसे तिरछा करें। किनारे जमने तक 2–3 मिनट पकाएँ। ऑमलेट के एक तरफ़ पकी हुई सब्ज़ियों का 1/4 भाग और 1 छोटा चम्मच फ़ेटा चीज़ छिड़कें।","ऑमलेट को धीरे से आधा मोड़ें और पूरी तरह जमने तक 1–2 मिनट और पकाएँ। प्लेट में निकालें और बाक़ी ऑमलेट के लिए यही दोहराएँ। ब्रेड के स्लाइस को हल्का टोस्ट करें।"]))
r.append(R(6588001,"टर्की और बीन्स बरिटो बाउल",
"यह टर्की और बीन्स बरिटो बाउल प्रोटीन, फ़ाइबर और ताज़ी सामग्री का संतुलन देता है, जो इसे एक पौष्टिक और स्वादिष्ट भोजन बनाता है। बरिटो बाउल बनाने से टॉर्टिला रैप का कार्ब हट जाता है।",
"4","1 बाउल",
["1 बड़ा चम्मच जैतून का तेल","1 पाउंड कीमा टर्की (एक्स्ट्रा लीन)","1 छोटा चम्मच चिली पाउडर","1/2 छोटा चम्मच जीरा","1/2 छोटा चम्मच पैपरिका","1/8 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च","1 मध्यम लाल शिमला मिर्च (स्लाइस की हुई)","1 मध्यम प्याज़ (स्लाइस किया हुआ)","1 कप रोमा (प्लम) टमाटर (टुकड़ों में कटे हुए)","1 कप ब्राउन राइस (पका हुआ)","1 कप काली बीन्स (कम सोडियम वाली, पानी निथारी और धुली हुई)","2 कप बटर लेट्यूस (बारीक कटा हुआ)","1/8 कप कम वसा वाला मैक्सिकन मिश्रित चीज़ (कसा हुआ)","1/2 कप ताज़ा धनिया पत्ती (कटी हुई)","1 साबुत नीबू (परोसने के लिए फाँकों में कटा हुआ)"],
["एक बड़ी कड़ाही में मध्यम आँच पर जैतून का तेल गरम करें और कीमा टर्की को भूरा होने तक पकाएँ, पकते समय उसे चम्मच से तोड़ते रहें।","कड़ाही में चिली पाउडर, जीरा, पैपरिका, कोशर नमक और काली मिर्च डालें और मसालों को भूनने के लिए 3 मिनट पकाएँ।","शिमला मिर्च और प्याज़ डालें और नरम होने तक पकाएँ। कटे हुए टमाटर डालें और अच्छी तरह मिलाएँ।","मिश्रण को लगभग 10 मिनट धीमी आँच पर पकाएँ ताकि स्वाद आपस में मिल जाएँ और सामग्री अंदर तक गरम हो जाए।","एक अलग कड़ाही में चावल और काली बीन्स को एक साथ गरम करें।","हर बाउल को सजाने के लिए, ¼ कप ब्राउन राइस, ¼ कप काली बीन्स, ½ कप लेट्यूस और लगभग ½ कप कीमा टर्की का मिश्रण परत-दर-परत रखें।","हर बाउल के ऊपर लगभग 1 बड़ा चम्मच कसा हुआ मैक्सिकन मिश्रित चीज़ और कटी हुई धनिया पत्ती डालें। साथ में नीबू की फाँकें परोसें।"]))
r.append(R(6588051,"फ़िश टैको",
"किसने कहा कि मैक्सिकन खाना सेहतमंद नहीं हो सकता? यह रेसिपी साबित करती है कि यह सेहतमंद और स्वादिष्ट दोनों हो सकता है! इस तेज़ और आसान व्यंजन से अपने मेहमानों को प्रभावित करें। इस रेसिपी के लिए आप कोई भी सख़्त सफ़ेद मछली, या शाकाहारी विकल्प के लिए एक्स्ट्रा फ़र्म टोफ़ू भी इस्तेमाल कर सकते हैं।",
"8","1 टैको",
["1/2 कप सालसा या पिको डे गायो","1 छोटा नीबू (रस निकाला हुआ)","1 बड़ा चम्मच ताज़ा धनिया पत्ती (कटी हुई)","1 छोटा चम्मच चिली पाउडर","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 1/4 पाउंड सख़्त सफ़ेद मछली, जैसे तिलापिया या हैलिबट","1/2 कप सादा फ़ैट-फ़्री ग्रीक योगर्ट","1 बड़ा चम्मच हॉट सॉस","8 छोटे 6 इंच के मक्के के टॉर्टिला (गरम किए हुए)"],
["एक मध्यम कटोरे में सालसा, नीबू का रस, धनिया पत्ती, चिली पाउडर, नमक और काली मिर्च को फेंटकर मिलाएँ। अलग रख दें।","एक बड़े सॉते पैन पर कुकिंग स्प्रे लगाएँ। मछली को मध्यम आँच पर हर तरफ़ 2 मिनट भूनें। मछली पर सालसा का मिश्रण डालें और 3 मिनट और भूनें।","मछली को पैन से निकालें और काँटे से उसे रेशों में तोड़ें, उसमें सालसा का मिश्रण मिलाएँ।","एक छोटे कटोरे में योगर्ट और हॉट सॉस मिलाएँ। मछली को 8 टॉर्टिला में बराबर बाँटें और हर एक के ऊपर योगर्ट सॉस की एक डली रखें।"]))
r.append(R(6588125,"क्रॉक पॉट चिकन काचातोरे",
"यह क्लासिक चिकन काचातोरे की एक आसान रेसिपी है। यह उन जल्दी पकाने वालों के लिए एकदम सही है जो एक स्वादिष्ट, किफ़ायती विकल्प चाहते हैं।",
"6","1 चिकन जाँघ + 1 कप सॉस",
["1 प्याज़ (स्लाइस किया हुआ)","1 साबुत शिमला मिर्च (बीज निकाली हुई और स्लाइस की हुई)","6 औंस टमाटर पेस्ट (6 औंस, बिना नमक मिलाया)","14 1/2 औंस टमाटर (14.5 औंस, टुकड़ों में कटे हुए)","3 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच इटैलियन सीज़निंग","मध्यम आकार की चिकन जाँघें (त्वचा हटाई हुई)"],
["सारी सामग्री को क्रॉक पॉट में रखें।","तेज़ आँच पर 4 घंटे पकाएँ।","चाहें तो चिकन को साबुत गेहूँ के रोटिनी पास्ता के ऊपर परोसें।"]))
r.append(R(6589479,"साबुत गेहूँ की आयरिश सोडा ब्रेड",
"यह साबुत गेहूँ की आयरिश सोडा ब्रेड भरपेट और सरल है, जिसमें हल्का मेवे जैसा स्वाद है। यह बिना यीस्ट के जल्दी बन जाती है, जो इसे तब एक बढ़िया विकल्प बनाती है जब आप भोजन के साथ या स्नैक के रूप में ताज़ी घर की बनी ब्रेड का आनंद लेना चाहते हों।",
"24","1 स्लाइस",
["2 कप साबुत गेहूँ का आटा","1 कप मैदा (ऑल-पर्पज़ आटा)","1/2 कप सुनहरी किशमिश","1 1/2 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच नमक","2 कप कम वसा वाली छाछ (बटरमिल्क) (कम वसा वाली)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें और बेकिंग शीट पर बेकिंग पेपर बिछाएँ।","एक बड़े मिक्सिंग बाउल में साबुत गेहूँ का आटा, मैदा, बेकिंग सोडा, नमक और किशमिश मिलाएँ।","सूखी सामग्री के बीच में गड्ढा बनाएँ और सारी छाछ एक साथ डालें। रबर स्पैचुला से सामग्री को बस मिलने तक धीरे से मिलाएँ। ज़्यादा न मिलाएँ।","आटे को बेकिंग पेपर पर निकालें और गोल लोफ़ का आकार दें। तेज़ चाकू से आटे के ऊपर लगभग 1/2 इंच गहरा X का निशान काटें।","बीच वाली रैक पर 30 मिनट बेक करें या जब तक वह सख़्त और सुनहरी भूरी न हो जाए।"]))
r.append(R(6590213,"पीनट बटर, 1 बड़ा चम्मच",
"पीनट बटर की पोषण संबंधी जानकारी",
"1","1 बड़ा चम्मच",["1 बड़ा चम्मच पीनट बटर (प्राकृतिक)"],[]))
r.append(R(6591894,"लहसुन और तेल में भुना हुआ पालक",
"यह \"रेसिपी\" बहुत सरल है, लेकिन यह ताज़े पालक को पकाने का एक आसान, सेहतमंद और स्वादिष्ट तरीका है। किसी भी तरह की सब्ज़ियाँ, जैसे फूलगोभी, ब्रोकली, शिमला मिर्च, आलू और/या हरी बीन्स, को बस नरम होने तक ब्लैंच किया जा सकता है, और इसी तरह तैयार किया जा सकता है।",
"4","लगभग 1/2 कप",
["2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","2 1/4 पाउंड पालक (छँटा हुआ, अच्छी तरह धोया और सुखाया हुआ)","3 कली लहसुन (बारीक कटी हुई)","चुटकी भर कुटी हुई लाल मिर्च के फ़्लेक्स","1/8 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच ताज़ी पिसी काली मिर्च","1 नीबू (आधा कटा हुआ)"],
["एक बहुत बड़ी कड़ाही में तेज़ आँच पर तेल को बहुत गरम होने तक गरम करें। पालक डालें (आपको कई बार में करना पड़ सकता है) और चलाते हुए लगभग 1-2 मिनट पकाएँ; पालक चटख हरा हो जाना चाहिए और थोड़ा गल जाना चाहिए। लहसुन और लाल मिर्च के फ़्लेक्स डालें और लगातार चलाते हुए पकाना जारी रखें, जब तक लहसुन की खुशबू न आने लगे, लगभग 30 सेकंड।","पालक को आँच से उतारें और नमक और काली मिर्च डालें। मिलाने के लिए अच्छी तरह उछालें, और साथ में नीबू (पालक पर रस निचोड़ने के लिए) रखकर परोसें।"]))
r.append(R(6593132,"मलाईदार चिकन और ब्रोकली तुलसी पेस्टो सलाद",
"बिना ज़्यादा ख़र्च किए चिकन सलाद का एक ताज़ा रूप आज़माएँ। यह मधुमेह के अनुकूल व्यंजन किफ़ायती है और दोपहर के भोजन या हल्के रात के खाने के लिए एक बढ़िया विकल्प है। अपने भोजन में कुछ कुरकुरापन जोड़ने के लिए इसे साबुत अनाज के क्रैकर्स के साथ परोसकर देखें।",
"4","¾ कप चिकन सलाद + 2 कप हरी पत्तेदार सब्ज़ियाँ",
["2 बड़े चम्मच नीबू का रस (1 छोटे नीबू से)","1/2 मध्यम शैलट (बारीक कटा हुआ)","2 कप पका हुआ चिकन (कटा हुआ)","2 कप ब्रोकली (कटी हुई)","2 बड़े चम्मच पेस्टो सॉस","1/4 कप कम वसा वाली जैतून के तेल की मेयोनेज़","8 कप मिली-जुली हरी पत्तेदार सब्ज़ियाँ","1/4 छोटा चम्मच नमक","1 कप चेरी टमाटर (आधे कटे हुए)"],
["नीबू का रस एक छोटे कटोरे में शैलट के साथ निचोड़ें। लगभग 10 मिनट रहने दें।","चिकन और ब्रोकली को एक मध्यम कटोरे में मिलाएँ।","शैलट और नीबू के रस वाले कटोरे में पेस्टो, मेयो, नमक और काली मिर्च डालें। मिलाने के लिए फेंटें और चिकन और ब्रोकली वाले कटोरे में डालें।","चिकन सलाद को मिली-जुली हरी पत्तेदार सब्ज़ियों और चेरी टमाटर के ऊपर परोसें।"]))
