r.append(R(6593896,"किफ़ायती टूना पास्ता सलाद",
"आप इस टूना सलाद को पास्ता के बिना भी आज़मा सकते हैं और इसे लेट्यूस की परत पर या किसी भरपेट सलाद के ऊपर परोस सकते हैं। यह तेज़ और किफ़ायती भोजन एक सेहतमंद दोपहर या रात का खाना बनता है।",
"6","1 कप",
["1 1/2 कप बिना पका क्विनोआ पास्ता","2 डंठल अजवाइन (सेलरी) (टुकड़ों में कटे हुए)","2 मध्यम गाजर (टुकड़ों में कटी हुई)","1/2 मध्यम लाल शिमला मिर्च (टुकड़ों में कटी हुई)","1/4 छोटा प्याज़ (टुकड़ों में कटा हुआ)","1/4 कप हरे जैतून (टुकड़ों में कटे हुए)","11 औंस फ़्लेवर वाला ताज़ा टूना (पानी में पाउच)","1/4 कप सादा फ़ैट-फ़्री ग्रीक योगर्ट","3 बड़े चम्मच लाइट मेयोनेज़","1/4 छोटा चम्मच काली मिर्च"],
["पैकेट पर दिए निर्देशों के अनुसार पास्ता पकाएँ, नमक न डालें। पास्ता का पानी निथारें और उसे ठंडे पानी से धोएँ।","एक मध्यम कटोरे में बाक़ी सामग्री मिलाएँ। पास्ता डालें और लपेटने के लिए उछालकर मिलाएँ। परोसें।"]))
r.append(R(6594166,"झींगे के साथ ताज़ा मक्का, टमाटर और एवोकाडो सलाद",
"लेखिका अविवा गोल्डफ़ार्ब को यह स्वादिष्ट रेसिपी शॉन आस्क्यू से मिली, जो बेला बेथेस्डा हेयर सैलून में काम करते हैं। यह रेसिपी वसंत और गर्मियों में अपने चरम पर होती है, जब किसानों के बाज़ार की ताज़ी सब्ज़ियाँ झींगे और एवोकाडो को चमकने में मदद करती हैं। इसे साबुत गेहूँ के डिनर रोल्स के साथ परोसें और आपने मधुमेह के अनुकूल बिल्कुल सही भोजन के लिए \"सिक्स ओ'क्लॉक स्क्रैम्बल\" की समस्या हल कर ली होगी!",
"8","1 ½ कप",
["1 पाउंड झींगे (मध्यम या बड़े, छिले और नस निकाले हुए)","2 कप चेरी टमाटर (आधे कटे हुए)","2 मध्यम एवोकाडो (छिले और चौकोर टुकड़ों में कटे हुए)","2 साबुत भुट्टे मक्का (दाने काटे हुए (अगर ताज़ा स्वीट कॉर्न है तो पकाने की ज़रूरत नहीं। अगर नहीं, तो उसे 3 मिनट भाप में पकाएँ))","3 औंस फ़ेटा चीज़ (कम वसा वाला, चौकोर टुकड़ों में कटा हुआ, या मैक्सिकन केसो फ़्रेस्को या कोटिजा इस्तेमाल करें)","1/4 कप ताज़ी तुलसी (पतली कतरों में कटी हुई)","1 बड़ा चम्मच बाल्सैमिक सिरका (स्वादानुसार)","1 बड़ा चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1/8 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च (ताज़ी पिसी हुई, या स्वादानुसार)"],
["पहले से करें या किसी और को सौंपें: झींगे पकाकर रेफ़्रिजरेटर में रखें, टमाटर आधे काटें, भुट्टों से मक्का के दाने निकालें, या पूरा सलाद तैयार करके रेफ़्रिजरेटर में रखें (एवोकाडो को परोसने से ठीक पहले ही काटें और डालें)।","झींगों को पैन में तलें, भाप में पकाएँ या ग्रिल करें जब तक वे गुलाबी न हो जाएँ, कुल 3–4 मिनट। (इस बीच, अगर रोल्स परोस रहे हैं तो उन्हें गरम करें।) झींगों को छोड़कर सारी सामग्री को एक बड़े परोसने वाले कटोरे में मिलाएँ। झींगे सलाद के ऊपर परोसें।","स्वाद बढ़ाने के लिए सलाद में 1/4 छोटा चम्मच अजवाइन के बीज या जीरा और 1 बड़ा चम्मच ताज़ा नीबू का रस डालें।"]))
